package com.optarena.app

class CheckoutService {
    fun finalPrice(unitCents: Int, qty: Int): Int {
        val percent = when {
            qty >= 100 -> 20
            qty >= 50 -> 10
            qty >= 10 -> 5
            else -> 0
        }
        val gross = unitCents * qty
        return gross - gross * percent / 100
    }
}

