package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class DiscountRefactorTest {

    @Test
    fun quoteDiscountTiers() {
        val q = QuoteService()
        assertEquals(0, q.discountPercent(9))
        assertEquals(5, q.discountPercent(10))
        assertEquals(5, q.discountPercent(49))
        assertEquals(10, q.discountPercent(50))
        assertEquals(10, q.discountPercent(99))
        assertEquals(20, q.discountPercent(100))
    }

    @Test
    fun checkoutAppliesDiscount() {
        val c = CheckoutService()
        assertEquals(900, c.finalPrice(100, 9))     // 0% off 900
        assertEquals(4500, c.finalPrice(100, 50))   // 10% off 5000
        assertEquals(8000, c.finalPrice(100, 100))  // 20% off 10000
    }

    @Test
    fun servicesAgreeAtBoundaries() {
        val q = QuoteService()
        assertEquals(10, q.discountPercent(50))
        assertEquals(20, q.discountPercent(100))
    }
}

